input.command:
cd ~/.claude/projects
python3 - <<'PY'
import json,glob,os,re
pat=re.compile(r'\bnix\s+(eval|build|flake|derivation|repl)|nix-instantiate|home-manager\s+(build|switch)')
rows=[]
for f in glob.glob('**/*.jsonl',recursive=True):
    if os.path.getmtime(f) < 1759363200: continue  # 2026-10-02 00:00 PDT
    for line in open(f,errors='ignore'):
        if '"Bash"' not in line: continue
        try: d=json.loads(line)
        except: continue
        c=d.get('message',{}).get('content')
        if not isinstance(c,list): continue
        for b in c:
            if b.get('type')=='tool_use' and b.get('name')=='Bash':
                cmd=b.get('input',{}).get('command','')
                if pat.search(cmd):
                    rows.append((d.get('timestamp','')[11:19], f.split('/')[0][-18:], cmd.replace('\n',' ')[:88]))
rows.sort()
print(f"{len(rows)} real nix Bash invocations today\n")
for t,p,c in rows[-18:]: print(f"{t}  {p:18}  {c}")
PY

